package com.shipflow.billing;
import java.nio.charset.StandardCharsets; import java.nio.file.*; import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class BillingMapperXmlTest { @Test void mapperUsesTenantPredicatesUniquenessOptimisticLockAndNoFinancialMutation() throws Exception { String xml=Files.readString(Path.of("src/main/resources/mapper/billing/BillingMapper.xml"),StandardCharsets.UTF_8); assertThat(xml).contains("tenant_id=#{tenantId}","provider_id=#{providerId}","file_hash=#{fileHash}","version=version+1","reconciliation_status='PENDING_CONFIRMATION'","current_fee"); assertThat(xml.toUpperCase()).doesNotContain("UPDATE SHIPMENT_ORDER","UPDATE FEE_ADJUSTMENT","UPDATE SHIPMENT_QUOTE_SNAPSHOT","UPDATE WAREHOUSE_MEASUREMENT","SELECT *"); } }
